import{_ as a,o as t,c as o,a3 as r}from"./chunks/framework.BlfGB29P.js";const g=JSON.parse('{"title":"Custom blocks and template packages","description":"","frontmatter":{"title":"Custom blocks and template packages"},"headers":[],"relativePath":"en/projects/blocks-for-ha/custom-blocks.md","filePath":"en/projects/blocks-for-ha/custom-blocks.md","lastUpdated":1792754181000}'),n={name:"en/projects/blocks-for-ha/custom-blocks.md"};function s(i,e,l,c,d,p){return t(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="custom-blocks-and-template-packages" tabindex="-1">Custom blocks and template packages <a class="header-anchor" href="#custom-blocks-and-template-packages" aria-label="Permalink to &quot;Custom blocks and template packages&quot;">​</a></h1><p>Since <strong>0.1.18</strong>, <strong>Block-/Template-Editor</strong> beside the automation name opens a dialog occupying 95% of the viewport width and height. On phones it uses 98% with internal scrolling. Forms define the block; the right side shows a real Blockly preview, HA output with sample values and copyable package JSON. The app editor currently uses German labels.</p><h2 id="create-and-apply" tabindex="-1">Create and apply <a class="header-anchor" href="#create-and-apply" aria-label="Permalink to &quot;Create and apply&quot;">​</a></h2><ol><li>Enter package ID, version, name, author, licence and description, or select <strong>Beispiel laden</strong>.</li><li>Add one or several blocks: <strong>value/Jinja</strong>, <strong>condition/Jinja</strong>, <strong>action/HA YAML</strong> or <strong>trigger/HA YAML</strong>.</li><li>Add text, number, Boolean or entity fields and Number, String, Boolean or Value inputs.</li><li>Enter the Jinja expression or declarative HA mapping and review the preview.</li><li><strong>Übernehmen</strong> installs the package locally. Blocks appear in <strong>Benutzerdefiniert</strong>, immediately before Search.</li></ol><p>Enter Jinja expressions without outer template delimiters. Placeholders such as <code>${ENTITY}</code> refer to field or input names. Fields are substituted using their types; value inputs are parenthesised expressions. HA mappings use entire JSON values such as <code>{&quot;$field&quot;:&quot;ENTITY&quot;}</code> or <code>{&quot;$input&quot;:&quot;VALUE&quot;}</code>. <a href="./catalog/sensor-light">Sensor and light</a> provides complete examples.</p><h2 id="import-and-publication" tabindex="-1">Import and publication <a class="header-anchor" href="#import-and-publication" aria-label="Permalink to &quot;Import and publication&quot;">​</a></h2><ul><li><strong>Paste code:</strong> paste package JSON into “JSON-Code oder ZIP importieren”, select <strong>JSON prüfen</strong>, review and <strong>Übernehmen</strong>.</li><li><strong>Read ZIP:</strong> select the package file, review and <strong>Übernehmen</strong>.</li></ul><p><strong>JSON herunterladen</strong>, <strong>Code kopieren</strong> and <strong>Katalog-ZIP herunterladen</strong> export the same package. ZIP contains <code>block-package.json</code> and <code>README.md</code>. Open-source pages explain packages and provide code/downloads. The separate <a href="https://visualstudio.ugso-software.de/blocks" target="_blank" rel="noreferrer">catalog</a> receives a dedicated block-package page. Publication requires manual review; the editor does not upload automatically. <a href="./catalog/">Catalog and sample</a>.</p><h2 id="storage-and-conflicts" tabindex="-1">Storage and conflicts <a class="header-anchor" href="#storage-and-conflicts" aria-label="Permalink to &quot;Storage and conflicts&quot;">​</a></h2><p>Package format: <code>ugso-ha-block-package</code>, <code>schemaVersion: 1</code>. IDs use lowercase letters, digits and single underscores. Installed packages persist in the current browser. Project format <strong>3</strong> embeds used packages and their dependencies. Formats 1 and 2 remain readable. Failed project imports do not install new definitions.</p><p>Identical packages can be imported again. Existing IDs with different content or versions are rejected. Give a fork a new package ID; automatic updates and uninstall remain future work. Dependencies must match exact versions and be installed or embedded together in a project. Cycles are rejected.</p><p>Limits: 16 installed packages, 32 blocks per package, 12 fields and 8 inputs per block; JSON up to 500,000 characters, ZIP up to 1 MB compressed and decompressed. Only the two specified ZIP entries are allowed.</p><h2 id="initial-editor-limits" tabindex="-1">Initial editor limits <a class="header-anchor" href="#initial-editor-limits" aria-label="Permalink to &quot;Initial editor limits&quot;">​</a></h2><p>This is an original HA-oriented form editor with Blockly preview. The original <a href="https://docs.blockly.com/guides/create-custom-blocks/blockly-developer-tools/" target="_blank" rel="noreferrer">Blockly Block Factory</a> is not embedded yet. Its raw block JSON alone has no HA mapping and is not a UGSo package. JavaScript/Python/PHP/Lua/Dart generators are neither imported nor executed.</p><p>Custom-editor dropdowns, variable fields, images, statement containers, mutators and dynamic connections remain on the roadmap. Value connections are type checked; existing blocks accepting only fixed numeric fields still reject dynamic numeric values.</p><p>Preview validates the package and supported HA structures without executing Jinja. Check device capabilities and valid parameters in HA. Numeric fields currently have no configurable min/max limits. The editor executes no HA actions. YAML exports native structures; YAML reimport creates the corresponding native representation. JSON project files preserve custom block shapes.</p>',16)])])}const m=a(n,[["render",s]]);export{g as __pageData,m as default};
